(function () {
'use strict';
var LS = 'vp-calc-state-v6';
var ROOM_CONFIG = {
  bath: { name: 'Ванная / Санузел', icon: '🛁', tip: '💧 100% влагозащита: удерживает до 100 л воды при затоплении сверху.', defaultArea: 4, defaultRooms: 1, defaultType: 'pvx' },
  bedroom: { name: 'Спальня', icon: '🛏', tip: '🌿 Эко-полотно без запаха + ниша под скрытый карниз ПК-5 для штор.', defaultArea: 12, defaultRooms: 1, defaultType: 'pvx' },
  kitchen: { name: 'Кухня', icon: '🍳', tip: '✨ Моющееся полотно: устойчиво к пару, легко очищается от жира.', defaultArea: 9, defaultRooms: 1, defaultType: 'pvx' },
  living: { name: 'Гостиная', icon: '🛋', tip: '⭐ Идеальная геометрия: теневой зазор EuroKRAAB и трековый свет.', defaultArea: 18, defaultRooms: 1, defaultType: 'pvx' },
  corridor: { name: 'Коридор', icon: '🚪', tip: '💡 Визуальное расширение со встроенными спотами или световой линией.', defaultArea: 6, defaultRooms: 1, defaultType: 'pvx' },
  flat: { name: 'Вся квартира / Несколько комнат', icon: '🏢', tip: '🎁 Скидка 10% на весь объём + ниша ПК-5 в подарок при заказе от 2-х комнат!', defaultArea: 45, defaultRooms: 3, defaultType: 'pvx' }
};

var ROOM_AREAS = {
  bedroom: 12,
  kitchen: 9,
  bath: 4,
  living: 18,
  corridor: 6
};

var state = {
  room: 'living',
  type: 'pvx',
  area: 18,
  rooms: 1,
  lights: 4,
  extras: {},
  fixEstimate: false,
  multi: { bedroom: 0, kitchen: 0, bath: 0, living: 0, corridor: 0 }
};

var PRICES = null;
var started = false;
var roots = [];

function load() {
  var el = document.querySelector('.prices-data');
  if (el) {
    try { PRICES = JSON.parse(el.textContent); } catch (e) { PRICES = null; }
  }
  if (!PRICES) return false;
  try {
    var saved = JSON.parse(localStorage.getItem(LS) || '{}');
    if (saved && typeof saved === 'object') {
      if (saved.type && PRICES.types[saved.type]) state.type = saved.type;
      if (typeof saved.area === 'number' && saved.area >= 1 && saved.area <= 1000) state.area = saved.area;
      if (typeof saved.rooms === 'number' && saved.rooms >= 1 && saved.rooms <= 20) state.rooms = saved.rooms;
      if (typeof saved.lights === 'number' && saved.lights >= 0 && saved.lights <= 100) state.lights = saved.lights;
      if (saved.extras && typeof saved.extras === 'object') state.extras = saved.extras;
      if (saved.room && ROOM_CONFIG[saved.room]) state.room = saved.room;
      if (saved.multi && typeof saved.multi === 'object') state.multi = saved.multi;
    }
  } catch (e) {}
  return true;
}

function save() {
  try {
    localStorage.setItem(LS, JSON.stringify(state));
  } catch (e) {}
}

function markStart() {
  if (started) return;
  started = true;
  try {
    if (window.ym) ym(99778844, 'reachGoal', 'calc_start');
  } catch (e) {}
}


function getSelectedRoomsCount() {
  if (!state.multi || typeof state.multi !== 'object') return 0;
  var count = 0;
  for (var k in state.multi) {
    count += (parseInt(state.multi[k], 10) || 0);
  }
  return count;
}

function calc() {
  if (!PRICES) return { ok: false };
  var t = PRICES.types[state.type] || PRICES.types.pvx;
  var area = Math.max(1, Math.min(1000, state.area));
  var canvas = area * t.canvas_price;
  var workMin = area * t.work_min;
  var workMax = area * t.work_max;
  var lights = state.lights * PRICES.lights.price_min;
  var lightsMax = state.lights * PRICES.lights.price_max;
  var extraMin = 0;
  var extraMax = 0;
  for (var k in state.extras) {
    if (state.extras[k] && PRICES.extras[k]) {
      extraMin += PRICES.extras[k].price_min;
      extraMax += PRICES.extras[k].price_max;
    }
  }

  // СКИДКА 10% СТРОГО И ТОЛЬКО ПРИ ЗАКАЗЕ ОТ 2-Х КОМНАТ
  var totalRooms = getSelectedRoomsCount();
  var isMulti = (totalRooms >= 2);
  var discountMul = isMulti ? 0.90 : 1.0;

  var totalMin = Math.round((canvas + workMin + lights + extraMin) * discountMul);
  var totalMax = Math.round((canvas + workMax + lightsMax + extraMax) * discountMul);

  return {
    ok: true,
    canvas: canvas,
    workMin: workMin,
    workMax: workMax,
    lights: lights,
    lightsMax: lightsMax,
    extraMin: extraMin,
    extraMax: extraMax,
    totalMin: totalMin,
    totalMax: totalMax,
    isMulti: isMulti,
    discountMul: discountMul,
    totalRooms: totalRooms
  };
}

function updateMultiCountersUI() {
  for (var r in state.multi) {
    var el = document.getElementById('cnt-' + r);
    if (el) {
      el.textContent = state.multi[r] || 0;
      var card = el.closest('[data-counter]');
      if (card) {
        card.classList.toggle('is-selected', (state.multi[r] || 0) > 0);
      }
    }
  }
  var resBox = document.getElementById('multiFlatResult');
  var roomsEl = document.getElementById('multiFlatRooms');
  var areaEl = document.getElementById('multiFlatArea');
  var flatBox = document.getElementById('calcMultiFlat');

  var totalR = getSelectedRoomsCount();
  var totalA = 0;
  for (var k in state.multi) {
    totalA += (state.multi[k] || 0) * (ROOM_AREAS[k] || 10);
  }

  var discBadge = resBox ? resBox.querySelector('.calc-discount-badge, .badge-red-sm') : null;

  if (totalR >= 2) {
    // 2 и более комнат -> показываем и активируем скидку 10%
    if (resBox) resBox.style.setProperty('display', 'inline-flex', 'important');
    if (roomsEl) roomsEl.textContent = totalR;
    if (areaEl) areaEl.textContent = totalA + ' м²';
    if (flatBox) flatBox.classList.add('is-active');

    if (!discBadge && resBox) {
      discBadge = document.createElement('span');
      discBadge.className = 'calc-discount-badge';
      resBox.appendChild(discBadge);
    }
    if (discBadge) {
      discBadge.textContent = 'Скидка 10%';
      discBadge.style.background = '#FFD600';
      discBadge.style.color = '#062619';
      discBadge.style.fontWeight = '700';
      discBadge.style.borderRadius = '6px';
      discBadge.style.padding = '2px 6px';
      discBadge.style.fontSize = '11px';
      discBadge.style.marginLeft = '6px';
      discBadge.style.display = 'inline-block';
    }
  } else if (totalR === 1) {
    // Ровно 1 комната -> скидки НЕТ!
    if (resBox) resBox.style.setProperty('display', 'inline-flex', 'important');
    if (roomsEl) roomsEl.textContent = totalR;
    if (areaEl) areaEl.textContent = totalA + ' м²';
    if (flatBox) flatBox.classList.remove('is-active');
    if (discBadge) {
      discBadge.remove();
    }
  } else {
    // 0 комнат -> ничего не выбрано, плашка полностью скрыта!
    if (resBox) resBox.style.setProperty('display', 'none', 'important');
    if (flatBox) flatBox.classList.remove('is-active');
    if (discBadge) {
      discBadge.remove();
    }
  }
}

function render() {
  var c = calc();
  if (!c.ok) return;

  roots.forEach(function (root) {
    // Room buttons active state
    root.querySelectorAll('[data-room-preset]').forEach(function (b) {
      var isAct = (b.dataset.roomPreset === state.room) && (!c.isMulti || state.room !== 'flat');
      b.classList.toggle('is-active', isAct);
      b.setAttribute('aria-pressed', isAct ? 'true' : 'false');
    });

    // Material radios
    root.querySelectorAll('[data-calc-type]').forEach(function (i) {
      i.checked = (i.value === state.type);
    });

    // Area & Rooms input values
    var area = root.querySelector('[data-calc-area]');
    if (area && document.activeElement !== area) area.value = state.area;
    var roomsOut = root.querySelector('[data-calc-rooms]');
    if (roomsOut) roomsOut.textContent = state.rooms;
    var lightsOut = root.querySelector('[data-calc-lights]');
    if (lightsOut) lightsOut.textContent = state.lights;

    // Checkboxes
    root.querySelectorAll('[data-calc-extra]').forEach(function (cb) {
      cb.checked = !!state.extras[cb.value];
    });

    // Room Tip Banner in Estimate
    var rBanner = root.querySelector('[data-estimate-room-banner]');
    if (rBanner) {
      var rConf = ROOM_CONFIG[state.room] || ROOM_CONFIG.living;
      var multiBadge = c.isMulti ? ' <span class="badge-red-sm" style="margin-left:6px">СКИДКА 10%</span>' : '';
      rBanner.innerHTML = '<div class="room-banner-box">' +
        '<div class="room-banner-head">' + rConf.icon + ' <strong>' + rConf.name + ' (' + state.area + ' м²)' + '</strong>' + multiBadge + '</div>' +
        '<div class="room-banner-tip">' + rConf.tip + '</div>' +
        '</div>';
    }

    // Estimate rows
    var rows = root.querySelector('[data-estimate-rows]');
    if (rows) {
      var t = PRICES.types[state.type] || PRICES.types.pvx;
      var html = '';
      html += '<div class="estimate__row"><span>1. Полотно (' + t.label + ', ' + state.area + ' м²)</span><strong>' + c.canvas.toLocaleString('ru-RU') + ' ₽</strong></div>';
      html += '<div class="estimate__row"><span>2. Профиль и чистый монтаж (' + state.area + ' м²)</span><strong>' + c.workMin.toLocaleString('ru-RU') + ' – ' + c.workMax.toLocaleString('ru-RU') + ' ₽</strong></div>';
      if (state.lights > 0) {
        html += '<div class="estimate__row"><span>3. Монтаж светильников (' + state.lights + ' шт.)</span><strong>' + c.lights.toLocaleString('ru-RU') + ' – ' + c.lightsMax.toLocaleString('ru-RU') + ' ₽</strong></div>';
      }
      if (c.extraMin > 0) {
        html += '<div class="estimate__row"><span>4. Дополнительные опции</span><strong>' + c.extraMin.toLocaleString('ru-RU') + ' – ' + c.extraMax.toLocaleString('ru-RU') + ' ₽</strong></div>';
      }
      if (c.isMulti) {
        html += '<div class="estimate__row estimate__row--discount" style="color:#FFD600; font-weight:700;"><span>🔥 Скидка 10% (от 2-х комнат)</span><strong>−10%</strong></div>';
      }
      rows.innerHTML = html;
    }

    // Total and installment
    var tot = root.querySelector('[data-estimate-total]');
    var inst = root.querySelector('[data-estimate-installment]');
    var hasArea = (typeof state.area === 'number' && state.area > 0);
    if (!hasArea) {
      if (tot) tot.textContent = 'Введите площадь';
      if (inst) inst.textContent = '';
    } else {
      if (tot) {
        tot.textContent = 'от ' + c.totalMin.toLocaleString('ru-RU') + ' до ' + c.totalMax.toLocaleString('ru-RU') + ' ₽';
      }
      if (inst) {
        var perMonth = Math.round(c.totalMin / 6);
        inst.textContent = '0% · от ' + perMonth.toLocaleString('ru-RU') + ' ₽/мес на 6 мес.';
      }
    }

    // Hidden field for form
    var sumF = root.querySelector('[data-calc-summary]');
    if (sumF) {
      sumF.value = (ROOM_CONFIG[state.room] ? ROOM_CONFIG[state.room].name : 'Потолок') +
        ', ' + state.area + ' м², ' + state.rooms + ' комн., ' + state.type + ', от ' + c.totalMin + ' до ' + c.totalMax + ' ₽';
    }
  });

  updateMultiCountersUI();
  save();
}

function wire(root) {
    // Multi-room counters (+ and - buttons)
  root.querySelectorAll('[data-room-counter]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var rType = btn.dataset.roomCounter;
      var dir = parseInt(btn.dataset.dir, 10);
      if (!state.multi) state.multi = { bedroom: 0, kitchen: 0, bath: 0, living: 0, corridor: 0 };
      state.multi[rType] = Math.max(0, (state.multi[rType] || 0) + dir);

      var totalR = getSelectedRoomsCount();
      var totalA = 0;
      for (var k in state.multi) {
        totalA += (state.multi[k] || 0) * (ROOM_AREAS[k] || 10);
      }

      state.rooms = totalR;
      if (totalR > 0) {
        state.area = totalA;
      } else {
        state.area = 18;
      }

      var areaInp = root.querySelector('[data-calc-area]');
      if (areaInp) areaInp.value = state.area;

      markStart();
      render();
    });
  });

  // Single Room Selector Presets
  root.querySelectorAll('[data-room-preset]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var roomKey = btn.dataset.roomPreset;
      state.room = roomKey;
      var rConf = ROOM_CONFIG[roomKey];
      if (rConf) {
        state.area = rConf.defaultArea;
        state.rooms = rConf.defaultRooms;
        if (rConf.defaultType && PRICES.types[rConf.defaultType]) {
          state.type = rConf.defaultType;
        }
      }
      // Reset multi counters
      state.multi = { bedroom: 0, kitchen: 0, bath: 0, living: 0, corridor: 0 };

      var areaInput = root.querySelector('[data-calc-area]');
      if (areaInput) {
        areaInput.value = state.area;
        var areaWrap = areaInput.closest('.field');
        if (areaWrap) areaWrap.classList.remove('invalid');
      }
      markStart();
      render();
    });
  });

  // Material radio changes
  root.querySelectorAll('[data-calc-type]').forEach(function (i) {
    i.addEventListener('change', function () {
      if (i.checked) { state.type = i.value; markStart(); render(); }
    });
  });

  // Area input
  var area = root.querySelector('[data-calc-area]');
  if (area) {
    area.addEventListener('input', function () {
      var v = parseInt(area.value.replace(/D/g, ''), 10);
      var wrap = area.closest('.field');
      if (isNaN(v) || v < 1 || v > 1000) {
        if (wrap) wrap.classList.add('invalid');
      } else {
        if (wrap) wrap.classList.remove('invalid');
        state.area = v;
        markStart();
        render();
      }
    });
  }

  // Steppers (rooms, lights)
  root.querySelectorAll('[data-step-btn]').forEach(function (b) {
    b.addEventListener('click', function () {
      var which = b.dataset.stepBtn;
      var d = parseInt(b.dataset.delta, 10);
      if (which === 'rooms') {
        state.rooms = Math.max(1, Math.min(20, state.rooms + d));
      } else if (which === 'lights') {
        state.lights = Math.max(0, Math.min(100, state.lights + d));
      }
      markStart();
      render();
    });
  });

  // Extras checkboxes
  root.querySelectorAll('[data-calc-extra]').forEach(function (cb) {
    cb.addEventListener('change', function () {
      state.extras[cb.value] = cb.checked;
      markStart();
      render();
    });
  });

  // Fix Price CTA Button
  var fixBtn = root.querySelector('[data-calc-fix]');
  if (fixBtn) {
    fixBtn.addEventListener('click', function () {
      var nameInp = root.querySelector('#cc-name');
      if (nameInp) nameInp.focus();
      try { if (window.ym) ym(99778844, 'reachGoal', 'calc_fix_click'); } catch (e) {}
    });
  }
}

function init() {
  roots = Array.prototype.slice.call(document.querySelectorAll('[data-calc-root]'));
  if (!roots.length) return;
  if (!load()) return;
  roots.forEach(wire);
  render();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

/* Wire area presets and WhatsApp link */
function syncPresetActiveState() {
  document.querySelectorAll('[data-calc-area-preset]').forEach(function (btn) {
    var a = parseInt(btn.dataset.calcAreaPreset, 10);
    btn.classList.toggle('is-active', a === state.area);
  });
}

document.querySelectorAll('[data-calc-area-preset]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    var a = parseInt(btn.dataset.calcAreaPreset, 10);
    if (a > 0) {
      state.area = a;
      var areaInput = document.querySelector('[data-calc-area]');
      if (areaInput) areaInput.value = a;
      render();
    }
  });
});

/* Update WhatsApp link dynamically without rooms */
var origRender = render;
render = function() {
  origRender();
  syncPresetActiveState();
  var c = calc();
  if (!c || !c.ok) return;
  var tLabel = (PRICES.types[state.type] || PRICES.types.pvx).label;
  var msg = 'Здравствуйте! Рассчитал на сайте натяжной потолок: ' + state.area + ' м², ' + tLabel + ', светильников: ' + state.lights + ' шт. Ориентировочная сумма: от ' + c.totalMin.toLocaleString('ru-RU') + ' до ' + c.totalMax.toLocaleString('ru-RU') + ' ₽. Подскажите, когда возможен бесплатный замер?';
  var encMsg = encodeURIComponent(msg);
  document.querySelectorAll('[data-calc-wa-link]').forEach(function (el) {
    el.href = 'https://wa.me/79274737177?text=' + encMsg;
  });
  document.querySelectorAll('[data-calc-tg-link]').forEach(function (el) {
    el.href = 'https://t.me/+79274737177?text=' + encMsg;
  });
  document.querySelectorAll('[data-calc-max-link]').forEach(function (el) {
    el.href = 'https://max.ru/';
  });
};

})();
